<?php
if (!defined('ABSPATH')) exit;
function gim_stripe_secret(){ return defined('GIM_STRIPE_SECRET_KEY')?GIM_STRIPE_SECRET_KEY:''; }
function gim_stripe_request($method,$path,$body=[]){ $key=gim_stripe_secret(); if(!$key)return new WP_Error('stripe_config','Stripe secret key is not configured.'); $args=['method'=>$method,'headers'=>['Authorization'=>'Bearer '.$key],'timeout'=>30]; if($body)$args['body']=$body; $r=wp_remote_request('https://api.stripe.com/v1/'.ltrim($path,'/'),$args); if(is_wp_error($r))return $r; $code=wp_remote_retrieve_response_code($r); $json=json_decode(wp_remote_retrieve_body($r),true); if($code<200||$code>=300)return new WP_Error('stripe_error',$json['error']['message']??'Stripe error.'); return $json; }
function gim_platform_fee_pence($service_pence){ $bps=defined('GIM_COMMISSION_BPS')?(int)GIM_COMMISSION_BPS:1000; return (int)round($service_pence*$bps/10000); }
function gim_create_checkout_for_job($job_id,$customer_id,$purpose='initial_service',$additional_work_id=null){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); if(!$job||!gim_job_owned_by_customer($job,$customer_id))return new WP_Error('forbidden','Forbidden.');
 $amount=0;$estimate_id=null;$meta=[];
 if($purpose==='initial_service'){ $e=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".gim_table('estimates')." WHERE job_id=%d AND status='accepted' ORDER BY id DESC LIMIT 1",$job_id)); if(!$e)return new WP_Error('estimate','Accepted estimate required.'); $amount=(int)$e->service_subtotal_pence; $estimate_id=$e->id; }
 elseif($purpose==='top_up_service'){ $aw=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('additional_work').' WHERE id=%d AND job_id=%d',$additional_work_id,$job_id)); if(!$aw||!in_array($aw->status,['customer_approved','payment_pending'],true))return new WP_Error('topup','Approved additional work required.'); $amount=(int)$aw->service_pence; $meta['additional_work_id']=$aw->id; }
 else return new WP_Error('purpose','Invalid purpose.'); if($amount<=0)return new WP_Error('amount','Payment amount must be positive.');
 $existing=$wpdb->get_row($wpdb->prepare("SELECT * FROM ".gim_table('payments')." WHERE job_id=%d AND purpose=%s AND status IN ('created','processing','captured') AND ".($additional_work_id?'additional_work_id=%d':'additional_work_id IS NULL')." ORDER BY id DESC LIMIT 1",...($additional_work_id?[$job_id,$purpose,$additional_work_id]:[$job_id,$purpose]))); if($existing&&$existing->status==='captured')return new WP_Error('paid','Already paid.');
 $ref=$existing?$existing->reference:gim_ref('GM-PAY'); if(!$existing){ $wpdb->insert(gim_table('payments'),['reference'=>$ref,'job_id'=>$job_id,'estimate_id'=>$estimate_id,'additional_work_id'=>$additional_work_id,'purpose'=>$purpose,'status'=>'created','amount_pence'=>$amount,'currency'=>'gbp','meta_json'=>gim_json(['platform_fee_pence'=>gim_platform_fee_pence($amount)]),'created_at'=>gim_now(),'updated_at'=>gim_now()]); $payment_id=$wpdb->insert_id; } else $payment_id=$existing->id;
 $success=gim_page_url('gim-payment-return',['payment'=>$ref,'session_id'=>'{CHECKOUT_SESSION_ID}']); $cancel=gim_page_url('gim-job',['ref'=>$job->reference]);
 $session=gim_stripe_request('POST','checkout/sessions',[
  'mode'=>'payment','success_url'=>$success,'cancel_url'=>$cancel,'client_reference_id'=>$ref,
  'line_items[0][price_data][currency]'=>'gbp','line_items[0][price_data][product_data][name]'=>'GOTITMATE '.($purpose==='top_up_service'?'additional work':'service payment'),'line_items[0][price_data][unit_amount]'=>$amount,'line_items[0][quantity]'=>1,
  'payment_intent_data[metadata][gim_payment_reference]'=>$ref,'payment_intent_data[metadata][gim_job_reference]'=>$job->reference,'payment_intent_data[metadata][gim_purpose]'=>$purpose
 ]); if(is_wp_error($session))return $session; $wpdb->update(gim_table('payments'),['status'=>'processing','stripe_session_id'=>$session['id']??null,'updated_at'=>gim_now()],['id'=>$payment_id]); gim_audit('payment.checkout_created','payment',$ref,['job'=>$job->reference]); return ['url'=>$session['url'],'reference'=>$ref]; }
function gim_capture_payment_from_stripe($payment_ref,$payment_intent_id){ global $wpdb; $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('payments').' WHERE reference=%s',$payment_ref)); if(!$p)return false; if($p->status==='captured')return true; $wpdb->update(gim_table('payments'),['status'=>'captured','stripe_payment_intent_id'=>$payment_intent_id,'updated_at'=>gim_now()],['id'=>$p->id]); if($p->purpose==='initial_service')$wpdb->update(gim_table('jobs'),['status'=>'payment_secured','updated_at'=>gim_now()],['id'=>$p->job_id]); elseif($p->purpose==='top_up_service'&&$p->additional_work_id)$wpdb->update(gim_table('additional_work'),['status'=>'payment_secured'],['id'=>$p->additional_work_id]); gim_audit('payment.captured','payment',$payment_ref,['payment_intent'=>$payment_intent_id]); return true; }
function gim_refund_payment($payment_id,$amount_pence,$reason='requested_by_customer'){ global $wpdb; $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('payments').' WHERE id=%d',$payment_id)); if(!$p||$p->status!=='captured'||!$p->stripe_payment_intent_id)return new WP_Error('payment','Captured payment required.'); $remaining=(int)$p->amount_pence-(int)$p->refunded_pence; if($amount_pence<=0||$amount_pence>$remaining)return new WP_Error('amount','Invalid refund amount.'); $r=gim_stripe_request('POST','refunds',['payment_intent'=>$p->stripe_payment_intent_id,'amount'=>$amount_pence,'reason'=>$reason]); if(is_wp_error($r))return $r; $new=(int)$p->refunded_pence+$amount_pence; $wpdb->update(gim_table('payments'),['refunded_pence'=>$new,'status'=>$new>=(int)$p->amount_pence?'refunded':'partially_refunded','updated_at'=>gim_now()],['id'=>$p->id]); gim_audit('payment.refunded','payment',$p->reference,['amount_pence'=>$amount_pence,'stripe_refund'=>$r['id']??'']); return $r; }
function gim_verify_stripe_signature($payload,$header){ if(!defined('GIM_STRIPE_WEBHOOK_SECRET')||!GIM_STRIPE_WEBHOOK_SECRET)return false; $parts=[]; foreach(explode(',',$header) as $p){[$k,$v]=array_pad(explode('=',$p,2),2,null); if($k&&$v)$parts[$k][]=$v;} $t=$parts['t'][0]??null; if(!$t||abs(time()-(int)$t)>300)return false; $expected=hash_hmac('sha256',$t.'.'.$payload,GIM_STRIPE_WEBHOOK_SECRET); foreach($parts['v1']??[] as $sig)if(hash_equals($expected,$sig))return true; return false; }
function gim_request_payout($job_id,$provider_user_id){ global $wpdb; $job=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('jobs').' WHERE id=%d',$job_id)); $p=gim_provider_profile($provider_user_id); if(!$job||!$p||(int)$job->provider_id!==(int)$p->id||$job->status!=='completed')return new WP_Error('forbidden','Payout cannot be requested.'); $sta=$wpdb->get_var($wpdb->prepare('SELECT decision FROM '.gim_table('assurance_runs').' WHERE job_id=%d ORDER BY id DESC LIMIT 1',$job_id)); if($sta!=='PASS')return new WP_Error('assurance','Service Transaction Assurance must pass before payout request.'); $open=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".gim_table('disputes')." WHERE job_id=%d AND status NOT IN ('resolved','closed')",$job_id)); if($open)return new WP_Error('dispute','Payout is held while a dispute is open.'); $existing=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('payouts').' WHERE job_id=%d ORDER BY id DESC LIMIT 1',$job_id)); if($existing)return $existing->id; $gross=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(amount_pence-refunded_pence),0) FROM ".gim_table('payments')." WHERE job_id=%d AND status IN ('captured','partially_refunded')",$job_id)); $service=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(amount_pence-refunded_pence),0) FROM ".gim_table('payments')." WHERE job_id=%d AND status IN ('captured','partially_refunded')",$job_id)); $fee=gim_platform_fee_pence($service); $provider=max(0,$gross-$fee); $ref=gim_ref('GM-PAYOUT'); $wpdb->insert(gim_table('payouts'),['reference'=>$ref,'job_id'=>$job_id,'provider_id'=>$p->id,'status'=>'requested','gross_pence'=>$gross,'platform_fee_pence'=>$fee,'provider_pence'=>$provider,'created_at'=>gim_now(),'updated_at'=>gim_now()]); gim_audit('payout.requested','payout',$ref); return $wpdb->insert_id; }
function gim_admin_release_payout($payout_id){ global $wpdb; if(!current_user_can('gim_manage_payments')&&!current_user_can('manage_options'))return new WP_Error('forbidden','Forbidden.'); $po=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('payouts').' WHERE id=%d',$payout_id)); if(!$po||$po->status!=='requested')return new WP_Error('payout','Payout unavailable.'); $p=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.gim_table('providers').' WHERE id=%d',$po->provider_id)); if(!$p||!$p->stripe_account_id||!$p->stripe_ready)return new WP_Error('stripe','Provider Stripe account is not ready.'); $r=gim_stripe_request('POST','transfers',['amount'=>(int)$po->provider_pence,'currency'=>'gbp','destination'=>$p->stripe_account_id,'metadata[gim_payout_reference]'=>$po->reference]); if(is_wp_error($r))return $r; $wpdb->update(gim_table('payouts'),['status'=>'released','stripe_transfer_id'=>$r['id']??null,'updated_at'=>gim_now()],['id'=>$po->id]); gim_audit('payout.released','payout',$po->reference,['transfer'=>$r['id']??'']); return true; }
